from pathlib import Path
import re,json,runpy
root=Path(__file__).resolve().parents[1]; folder=root/'tools/rec-fisica'
E=runpy.run_path(str(folder/'data.py'))['E']
source=(root/'inscricao-circunscricao.html').read_text(); styles=re.findall(r'<style>(.*?)</style>',source,re.S); scripts=re.findall(r'<script>(.*?)</script>',source,re.S)[:2]
nav=re.search(r'<nav[^>]*aria-label="Cadernos de estudo"[^>]*>.*?</nav>',source,re.S).group();nav=re.sub(r' aria-current="page"','',nav)
link='<a href="recuperacao-calor-lancamento.html">Calor e lançamento horizontal · 8 exercícios</a>'
if 'href="recuperacao-calor-lancamento.html"' not in nav:nav=nav.replace('</nav>',link+'</nav>')
nav=nav.replace('href="recuperacao-calor-lancamento.html"','href="recuperacao-calor-lancamento.html" aria-current="page"')
app=(folder/'app.js').read_text().replace('/* DATA */',json.dumps(E,ensure_ascii=False))
html='''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Calor e lançamento horizontal · 8 exercícios interativos</title><meta name="description" content="Lista de recuperação de física de 19 e 21 de outubro de 2026: mudanças de fase, curvas de aquecimento e lançamento horizontal com soluções interativas.">'''+''.join('<style>'+s+'</style>' for s in styles)+'''<style>.source-note{font-size:14px;padding:16px;background:#fbf0e5;border-left:3px solid #a04f2c}.values{min-height:100px}.toolbar select{font:inherit;color:inherit;padding:8px;border:1px solid var(--line);border-radius:5px}.live-drawing{max-width:800px}.full-steps li{overflow-wrap:anywhere}@media(max-width:600px){.live-drawing{margin:0 -6px}.values{min-height:150px}}</style>'''+''.join('<script>'+s+'</script>' for s in scripts)+'''</head><body><header class="site-header"><div class="masthead">Álgebra, passo a passo · Física · 1º ano</div>'''+nav+'''<h1>Calor e lançamento horizontal.<br>Acompanhe cada transformação.</h1><p class="intro">Os 8 exercícios da lista de recuperação de 19 e 21 de outubro de 2026, com todos os subitens, curvas de aquecimento e resfriamento e simulações dos movimentos.</p><div class="guide"><p><strong>Questões 1–5 · Calor:</strong> separe as variações de temperatura das mudanças de fase. Nos patamares, o calor transforma a matéria sem alterar a temperatura.</p><p><strong>Questões 6–8 · Movimento:</strong> a velocidade horizontal permanece constante; a gravidade muda a velocidade vertical. Compare as quedas e explore a velocidade do corredor.</p><p>Abra a solução, reproduza a simulação ou arraste o controle. Os botões de marcos permitem parar nos pontos importantes.</p></div><a href="#practice">Ir aos 8 exercícios ↓</a></header><main id="practice"><div class="toolbar"><span id="progress" aria-live="polite"></span><label>Assunto <select id="topic"><option value="all">Todos</option><option value="heat">Calor e mudanças de fase</option><option value="motion">Lançamento horizontal</option></select></label><label><input id="pending" type="checkbox"> Só pendentes</label><button id="print">Imprimir com soluções</button></div><p id="storage" hidden>O navegador não permitiu salvar o progresso. As marcações funcionam nesta sessão.</p><noscript>Ative JavaScript para exibir os exercícios e as simulações.</noscript><div id="exercises"></div><p id="empty" hidden>Nenhum exercício neste filtro. Troque o assunto ou desmarque “Só pendentes”.</p></main><footer>Fonte: Colégio Agostiniano Mendel, professor Willi, Física — 1ª série, lista de 19 e 21 de outubro de 2026. Enunciados transcritos do PDF fornecido. Diagramas reconstruídos; valores decimais aproximados. Progresso salvo somente neste navegador. KaTeX e fontes incorporados para uso offline.</footer><script>'''+app+'''</script></body></html>'''
(root/'recuperacao-calor-lancamento.html').write_text(html)
for p in root.glob('*.html'):
 if p.name=='recuperacao-calor-lancamento.html':continue
 def add(m):
  n=m.group()
  return n if 'href="recuperacao-calor-lancamento.html"' in n else n.replace('</nav>',link+'</nav>')
 p.write_text(re.sub(r'<nav[^>]*aria-label="Cadernos de estudo"[^>]*>.*?</nav>',add,p.read_text(),flags=re.S))
print('8 exercícios com soluções interativas; navegação integrada.')
